"gamma.stc_bin[7]", "gamma.stc_bin[8]", "gamma.stc_bin[9]", "tau", 
"tau.AD.extra", "tau.cluster.common"))) -> vcov

  # Center and scale predictors
  # Are you sure that baseline was not scaled? Results make little sense otherwise
  baseline = (baseline-57.83)
  age      = (age-36.52)/11.85
  gender   = (gender-0.74)/0.44
  rel      = (rel-0.72)/0.45
  employ   = (employ-0.37)/0.48
  educ     = (educ - 0.34)/0.48

  # Calculate contrast vector
  # I do not use the first component (TAU; used as reference?)
  D.treat = (treat1 - treat2)[-1]

  # Predict effect
  md = ((D.treat %*% d) +
          baseline * (D.treat %*% gamma.baseline) +
          age      * (D.treat %*% gamma.age     ) +
          gender   * (D.treat %*% gamma.gender  ) +
          rel      * (D.treat %*% gamma.rel     ) +
          employ   * (D.treat %*% gamma.employ  ) +
          educ     * (D.treat %*% gamma.educ    ))

  # Get variance
  X = c(D.treat, D.treat*baseline, D.treat*age, D.treat*gender,
        D.treat*rel, D.treat*employ, D.treat*educ)
  c(d, gamma.baseline, gamma.age, gamma.gender,
    gamma.rel, gamma.employ, gamma.educ) %>% names() -> mask
  V = vcov[mask, mask]

  # Calculate confidence intervals
  se = sqrt(X %*% V %*% X)
  lower = md - qnorm(.975) * se
  upper = md + qnorm(.975) * se
  res = cbind(md = md[1,1], se = se[1,1], lower = lower[1,1], upper = upper[1,1])

  # Return
  message("Comparing: [", paste(comp.names[treat1==1], collapse=" + "),
          "] vs. [", paste(comp.names[treat2==1], collapse=" + "), "]")
  return(res)
}

